import{_ as t,o,c as s,ag as a}from"./chunks/framework.B7PviQjB.js";const b=JSON.parse('{"title":"Put a bot to work","description":"Create a workspace bot, connect it to your Claude Code session, and give it work by mentioning it in chat.","frontmatter":{"title":"Put a bot to work","description":"Create a workspace bot, connect it to your Claude Code session, and give it work by mentioning it in chat.","type":"how-to"},"headers":[],"relativePath":"developers/bots.md","filePath":"developers/bots.md"}'),n={name:"developers/bots.md"};function i(r,e,d,l,c,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="put-a-bot-to-work" tabindex="-1">Put a bot to work <a class="header-anchor" href="#put-a-bot-to-work" aria-label="Permalink to &quot;Put a bot to work&quot;">​</a></h1><p>Create a workspace bot, connect it to your Claude Code session, and give it work by mentioning it in chat.</p><p>A bot is a member of your workspace with its own name and a <strong>Bot</strong> badge. When you mention it, your Claude Code session picks up the message, does the work, and answers in the thread as the bot.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>The <a href="/docs/developers/claude-code-plugin.html">Claude Code plugin</a> is installed, and <code>/wafflebase:setup</code> passes.</li><li>The CLI is version 0.7.0 or later. Check with <code>wafflebase --version</code>.</li></ul></div><h2 id="create-a-bot" tabindex="-1">Create a bot <a class="header-anchor" href="#create-a-bot" aria-label="Permalink to &quot;Create a bot&quot;">​</a></h2><ol><li>In the web app, click <strong>Settings</strong> in the sidebar.</li><li>Under <strong>Bots</strong>, click <strong>New bot</strong>.</li><li>Enter a name, such as <code>deck-bot</code>. Use 2 to 32 lowercase letters, digits, or hyphens.</li><li>Under <strong>Who will mention this bot?</strong>, keep <strong>Just me</strong>.</li><li>Click <strong>Create</strong>. The <strong>Connect</strong> dialog opens with a pairing code.</li></ol><p>From a terminal with a browser session, the same steps are:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bots</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deck-bot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bots</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pair-code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deck-bot</span></span></code></pre></div><h2 id="connect-it-to-claude-code" tabindex="-1">Connect it to Claude Code <a class="header-anchor" href="#connect-it-to-claude-code" aria-label="Permalink to &quot;Connect it to Claude Code&quot;">​</a></h2><ol><li><p>In Claude Code, run <code>/wafflebase:listen</code> with the code from the <strong>Connect</strong> dialog:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/wafflebase:listen 4F2K-9QXD</span></span></code></pre></div></li><li><p>Approve the <code>wafflebase agent pair</code> prompt. The bot&#39;s row in <strong>Settings → Bots</strong> changes to <strong>Listening</strong>.</p></li></ol><p>A code works once and expires after 10 minutes. If it expires, click <strong>New code</strong> in the <strong>Connect</strong> dialog, or run <code>wafflebase bots pair-code deck-bot</code>.</p><p>The next time, start listening by name. You don&#39;t need a new code on the same computer:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/wafflebase:listen deck-bot</span></span></code></pre></div><p>To connect a server instead of Claude Code, run <code>wafflebase agent pair &lt;code&gt;</code> there. Each computer you connect shows as a host under the bot.</p><p>A computer keeps one bot per name. Pairing a bot with the same name from another workspace or server fails and keeps the first one. Disconnect the extra host in <strong>Settings → Bots</strong>. To swap the bots, pair again with a new code and <code>--replace</code>.</p><p>A host holds a task for 10 minutes, and each reply it sends renews that. If a task runs longer with no reply, another host of the same bot can take it. The first host can then no longer reply to it or close it.</p><h2 id="give-it-work" tabindex="-1">Give it work <a class="header-anchor" href="#give-it-work" aria-label="Permalink to &quot;Give it work&quot;">​</a></h2><ol><li>In a channel, mention the bot in a message, such as <code>@deck-bot add a summary slide to the launch deck</code>. Or open a direct message with the bot and write to it.</li><li>Claude Code picks up the message and reads the thread it came from.</li><li>Approve the commands Claude asks about, as in any other session.</li><li>The bot answers in the thread.</li></ol><p>Edits to documents run as you, not as the bot, so the document history shows your name. Because the bot acts with your access, it reads only your messages and its own in the thread; replies from other people never reach your Claude Code.</p><h2 id="know-the-limits" tabindex="-1">Know the limits <a class="header-anchor" href="#know-the-limits" aria-label="Permalink to &quot;Know the limits&quot;">​</a></h2><ul><li><strong>Only you can give it work.</strong> The bot answers only its owner. A mention from anyone else does nothing for now. <strong>Any member</strong> shows as <em>Available with team bots</em>.</li><li><strong>Your session is dedicated to the bot while it listens.</strong> Press Esc to talk to Claude yourself. Run <code>/wafflebase:listen deck-bot</code> to resume.</li><li><strong>One task at a time.</strong> Messages that arrive while Claude works wait their turn.</li><li><strong>The bot is offline when the session ends.</strong> Its row shows <strong>Offline</strong> with the time it was last seen. Messages you send while it is offline wait until it listens again.</li><li><strong>A bot doesn&#39;t answer other bots.</strong> A message posted by a bot never starts a task.</li></ul><h2 id="keep-its-key-safe" tabindex="-1">Keep its key safe <a class="header-anchor" href="#keep-its-key-safe" aria-label="Permalink to &quot;Keep its key safe&quot;">​</a></h2><p>Pairing stores the bot&#39;s key on your computer in <code>~/.wafflebase/agents/&lt;bot&gt;.json</code>, readable only by you. The key stays in your Claude Code: it is never shown, and it is not used by any other <code>wafflebase</code> command. Your own sign-in stays separate.</p><p>To disconnect every computer, delete the bot: in <strong>Settings → Bots</strong>, click <strong>Delete</strong> on its row, or run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bots</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deck-bot</span></span></code></pre></div><p>Deleting a bot revokes its keys and removes it from the workspace. Its messages stay, under its name. You can delete a bot you created; a workspace owner can delete any bot.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>wafflebase bots list</code></td><td>List the workspace&#39;s bots, owners, and connected hosts</td></tr><tr><td><code>wafflebase bots create &lt;name&gt;</code></td><td>Create a bot you manage</td></tr><tr><td><code>wafflebase bots pair-code &lt;name-or-id&gt;</code></td><td>Get a pairing code</td></tr><tr><td><code>wafflebase bots delete &lt;name-or-id&gt;</code></td><td>Delete a bot and disconnect its hosts</td></tr><tr><td><code>wafflebase agent pair &lt;code&gt; [--host-name &lt;name&gt;] [--replace]</code></td><td>Connect this computer to a bot</td></tr><tr><td><code>wafflebase agent list</code></td><td>List bots connected on this computer</td></tr><tr><td><code>wafflebase agent next &lt;bot&gt; [--wait &lt;seconds&gt;]</code></td><td>Take the bot&#39;s next task, waiting up to 240 seconds</td></tr><tr><td><code>wafflebase agent thread &lt;bot&gt; &lt;task-id&gt;</code></td><td>Read the thread a task came from</td></tr><tr><td><code>wafflebase agent reply &lt;bot&gt; &lt;task-id&gt; (&lt;body&gt; | --body-file -)</code></td><td>Answer as the bot; the listen skill sends the text on stdin so the shell never reads it. <code>--body-file &lt;path&gt;</code> sends a file&#39;s text, and the plugin always asks first</td></tr><tr><td><code>wafflebase agent complete &lt;bot&gt; &lt;task-id&gt; [--failed]</code></td><td>Close a task</td></tr></tbody></table><p>The <code>bots</code> commands need a browser session. The <code>agent</code> commands use only the bot&#39;s stored key, and ignore <code>--api-key</code>, <code>--server</code>, <code>--workspace</code>, and <code>WAFFLEBASE_API_KEY</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/developers/claude-code-plugin.html">Claude Code plugin</a> to install the plugin and control what asks for confirmation.</li><li><a href="/docs/developers/cli/automation.html">Automation and agents</a> for output formats and error codes.</li><li><a href="/docs/developers/cli/">Install and sign in</a> for the browser session the <code>bots</code> commands need.</li></ul>`,31)])])}const g=t(n,[["render",i]]);export{b as __pageData,g as default};
